mapper.select:
SELECT SRVC_CD , WH_CD , IN_NO , IN_EXPECTED_DATE , IN_EXPECTED_NO , IN_EXPECTED_SEQ , LOT_NO , VENDOR_CD , VENDOR_NM , PROD_CD , COALESCE(NULLIF(WMS.FN_GET_PROD_NM(SRVC_CD, WH_CD, PROD_CD), ''), '') AS PROD_NM , COALESCE(NULLIF(ORIGINAL_QTY, 0), 0) AS ORIGINAL_QTY , COALESCE(NULLIF(EXPECTED_QTY, 0), 0) AS EXPECTED_QTY , COALESCE(NULLIF(OPEN_QTY, 0), 0) AS OPEN_QTY , COALESCE(NULLIF(TEMP_QTY, 0), 0) AS TEMP_QTY , COALESCE(NULLIF(RECEIVED_QTY, 0), 0) AS RECEIVED_QTY , STATUS , RMK , IN_ZONE_CD , COALESCE(NULLIF(WMS.FN_GET_ZONE_NM(SRVC_CD, WH_CD, IN_ZONE_CD), ''), '') AS IN_ZONE_NM , COALESCE(NULLIF(WMS.FN_GET_USER_NM(REG_ID),''),'') AS REG_ID , TO_CHAR(REG_DATE,'YYYY-MM-DD') AS REG_DATE , COALESCE(NULLIF(WMS.FN_GET_USER_NM(UPD_ID),''),'') AS UPD_ID , TO_CHAR(UPD_DATE,'YYYY-MM-DD') AS UPD_DATE FROM WMS.TB_RECEIPT_D WHERE 1 = 1 AND SRVC_CD = #{srvcCd} AND WH_CD = #{whCd}
AND IN_NO = #{inNo}
ORDER BY IN_EXPECTED_SEQ

SELECT STATUS
  FROM WMS.TB_RECEIPT_H
 WHERE SRVC_CD = #{srvcCd}
   AND WH_CD   = #{whCd}
   AND IN_NO   = #{inNo}

mapper.insert:
INSERT INTO WMS.TB_RECEIPT_H (
    SRVC_CD
  , WH_CD
  , IN_NO
  , RECEIPT_CLS_CD
  , IN_EXPECTED_DATE
  , IN_EXPECTED_NO
  , VENDOR_CD
  , VENDOR_NM
  , IN_V_ID
  , IN_V_NO
  , IN_V_NM
  , TOTLINE
  , ORIGINAL_QTY
  , EXPECTED_QTY
  , STATUS
  , RMK
  , RECEIPT_TYPE
  , REG_ID
  , REG_DATE
) VALUES (
    #{srvcCd}
  , #{whCd}
  , #{inNo}
  , #{receiptClsCd}
  , #{inExpectedDate}
  , #{inExpectedNo}
  , #{vendorCd}
  , #{vendorNm}
  , #{inVId}
  , #{inVNo}
  , #{inVNm}
  , #{totline}
  , #{originalQty}
  , #{originalQty}
  , #{status}
  , #{rmk}
  , #{receiptType}
  , #{userId}
  , NOW()
)

INSERT INTO WMS.TB_RECEIPT_D (
    SRVC_CD
  , WH_CD
  , IN_NO
  , IN_EXPECTED_DATE
  , IN_EXPECTED_NO
  , IN_EXPECTED_SEQ
  , LOT_NO
  , VENDOR_CD
  , VENDOR_NM
  , PROD_CD
  , ORIGINAL_QTY
  , EXPECTED_QTY
  , OPEN_QTY
  , TEMP_QTY
  , RECEIVED_QTY
  , STATUS
  , RMK
  , IN_ZONE_CD
  , IN_LOC_CD
  , REG_ID
  , REG_DATE
) VALUES (
    #{srvcCd}
  , #{whCd}
  , #{inNo}
  , #{inExpectedDate}
  , #{inExpectedNo}
  , (
        SELECT COALESCE(NULLIF(MAX(IN_EXPECTED_SEQ), 0), 0) + 1
          FROM WMS.TB_RECEIPT_D
         WHERE 1 = 1
           AND SRVC_CD          = #{srvcCd}
           AND WH_CD            = #{whCd}
           AND IN_NO            = #{inNo}
           AND IN_EXPECTED_NO   = #{inExpectedNo}

    )
  , #{lotNo}
  , #{vendorCd}
  , #{vendorNm}
  , #{prodCd}
  , #{originalQty}
  , #{originalQty}
  , 0
  , 0
  , 0
  , #{status}
  , #{rmk}
  , #{inZoneCd}
  , #{inLocCd}
  , #{userId}
  , NOW()
)
